<section class="section"><div class="container"><?php if(!$run):?><div class="card empty-state"><span>⌛</span><h2>No merit list published</h2><p>The college has not published a merit result for this admission cycle.</p><a class="button button-outline" href="<?= url('admissions/'.$cycle['slug']) ?>">Back to cycle details</a></div><?php else:?><div class="section-heading"><div><span class="eyebrow">Frozen merit run v<?= (int)$run['version_no'] ?></span><h2>Published <?= format_date($run['published_at'],true) ?></h2></div><a class="button button-primary" href="<?= url('login') ?>">Open my private result</a></div><form method="get" action="<?= url('admissions/'.$cycle['slug'].'/merit') ?>" class="card workflow-filters"><label><span>Programme</span><select name="program"><option value="">All programmes</option><?php foreach($programs as $program):?><option value="<?= (int)$program['id'] ?>"<?= selected($programId,$program['id']) ?>><?= e($program['name']) ?> (<?= e($program['code']) ?>)</option><?php endforeach?></select></label><label><span>Merit category</span><select name="category"><option value="">All lists</option><?php foreach($categories as $item):?><option value="<?= e($item['merit_category']) ?>"<?= selected($category,$item['merit_category']) ?>><?= e($item['merit_category']) ?></option><?php endforeach?></select></label><button class="button button-outline">Filter list</button></form><section class="card table-card"><div class="table-wrap"><table><thead><tr><th>List rank</th><th>Application number</th><th>Programme</th><th>List</th><th>Overall rank</th><th>Result</th></tr></thead><tbody><?php foreach($entries as $entry):?><tr><td><b>#<?= (int)$entry['category_rank'] ?></b></td><td><b><?= e($entry['application_number']) ?></b></td><td><?= e($entry['program_name']) ?><small><?= e($entry['program_code']) ?></small></td><td><?= e($entry['merit_category']) ?><small><?= e($entry['quota']) ?></small></td><td>#<?= (int)$entry['overall_rank'] ?></td><td><?= e(ucwords(str_replace('_',' ',$entry['result_status']))) ?></td></tr><?php endforeach?></tbody></table></div><?php if(!$entries):?><div class="empty-inline">No rows match the selected filters.</div><?php endif?></section><?php $pages=max(1,(int)ceil($total/$perPage));if($pages>1):?><nav class="pagination" aria-label="Merit pages"><?php if($page>1):?><a href="<?= url('admissions/'.$cycle['slug'].'/merit?'.http_build_query(['program'=>$programId,'category'=>$category,'page'=>$page-1])) ?>">← Previous</a><?php endif?><b>Page <?= $page ?> of <?= $pages ?></b><?php if($page<$pages):?><a href="<?= url('admissions/'.$cycle['slug'].'/merit?'.http_build_query(['program'=>$programId,'category'=>$category,'page'=>$page+1])) ?>">Next →</a><?php endif?></nav><?php endif?><div class="compliance-callout"><b>Privacy notice</b><p>Names, email addresses, mobile numbers, dates of birth, category evidence and academic marks are never displayed on this public page.</p></div><?php endif?></div></section>
